"""Parse human-written money amounts without floating-point arithmetic."""

import re
from decimal import Decimal, InvalidOperation


def parse_amount(text: str) -> int:
    """Return integer cents, rounding ties away from zero.

    Whitespace around the amount, thousands commas, and a leading dollar
    sign are allowed. A sign can appear on either side of the dollar sign.
    """
    normalized = text.strip().replace(",", "")
    if not re.fullmatch(
        r"(?:[+-]?\$?|\$[+-]?)(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?",
        normalized,
    ):
        raise ValueError("Invalid money amount")
    try:
        amount = Decimal(normalized.replace("$", ""))
    except InvalidOperation as exc:
        raise ValueError("Invalid money amount") from exc
    if not amount.is_finite():
        raise ValueError("Money amount must be finite")

    # Work directly from the decimal digits so the caller's Decimal context
    # cannot reduce precision or change the rounding mode.
    sign, digits, exponent = amount.as_tuple()
    coefficient = 0
    for digit in digits:
        coefficient = coefficient * 10 + digit
    if coefficient == 0:
        return 0
    shift = exponent + 2
    if shift >= 0:
        cents = coefficient * 10**shift
    elif -shift > len(digits):
        cents = 0
    else:
        divisor = 10**(-shift)
        cents, remainder = divmod(coefficient, divisor)
        if (remainder * 2 > divisor):
            cents += 1
    return -cents if sign else cents

