def parse_amount(text: str) -> int:
    """Return integer cents, rounding half cents away from zero.

    Surrounding whitespace, thousands commas, and a leading dollar sign are
    accepted. A leading sign may appear on either side of the dollar sign.
    """
    normalized = text.strip().replace(",", "")
    if not _AMOUNT.fullmatch(normalized):
        raise ValueError("Invalid money amount")
    try:
        amount = Decimal(normalized.replace("$", ""))
    except InvalidOperation as exc:
        raise ValueError("Invalid money amount") from exc
    if not amount.is_finite():
        raise ValueError("Money amount must be finite")

    # Work directly from the decimal digits so the active Decimal context
    # cannot round a large amount before we round it to cents.
    sign, digits, exponent = amount.as_tuple()
    coefficient = 0
    for digit in digits:
        coefficient = coefficient * 10 + digit
    if coefficient == 0:
        return 0
    cent_exponent = exponent + 2
    if cent_exponent >= 0:
        cents = coefficient * 10**cent_exponent
