{"files":[{"path":"ledgerkit/invoice.py","content":""""Summarize invoice lines and percentage tax in integer cents."""

from decimal import Decimal, InvalidOperation, ROUND_HALF_UP, localcontext

from ledgerkit.lines import line_total


def invoice_summary(lines, tax_rate_pct) -> dict:
    """Sum lines and round tax half away from zero using the written rate."""
    subtotal = sum(line_total(*line) for line in lines)
    try:
        rate = Decimal(str(tax_rate_pct))
    except InvalidOperation as exc:
        raise ValueError("Tax rate must be numeric") from exc
    if not rate.is_finite():
        raise ValueError("Tax rate must be finite")

    decimal_subtotal = Decimal(subtotal)
    rate_parts = rate.as_tuple()
    with localcontext() as context:
        # Preserve every product digit and allow space for a whole-cent result.
        context.prec = max(
            28,
            len(decimal_subtotal.as_tuple().digits)
            + len(rate_parts.digits)
            + max(0, rate_parts.exponent)
            + 2,
        )
        tax = int(
            (decimal_subtotal * rate / Decimal(100)).quantize(
                Decimal(1), rounding=ROUND_HALF_UP
            )
        )
    return {"subtotal": subtotal, "tax": tax, "total": subtotal + tax}
"}]}

